import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused scale+add+clamp kernel
scale_clamp_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void scale_clamp_kernel(const float* input, float* output, int size, float scale, float clamp_min, float clamp_max) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx] * scale;
        val = fmaxf(clamp_min, fminf(clamp_max, val));
        output[idx] = val;
    }
}

torch::Tensor scale_clamp_cuda(torch::Tensor input, float scale, float clamp_min, float clamp_max) {
    auto output = torch::empty_like(input);
    int size = input.numel();
    const int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;
    scale_clamp_kernel<<<grid_size, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), size, scale, clamp_min, clamp_max);
    return output;
}
"""

# Custom fused logsumexp+mish kernel
logsumexp_mish_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

template <typename T>
__device__ T warp_reduce_max(T val) {
    for(int offset=16; offset>0; offset/=2) 
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

template <typename T>
__device__ T warp_reduce_sum(T val) {
    for(int offset=16; offset>0; offset/=2) 
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void logsumexp_mish_kernel(const float* input, float* output, int B, int H) {
    extern __shared__ float shared[];
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    // Find max value in row
    float max_val = -INFINITY;
    for(int i=tid; i<H; i+=blockDim.x) {
        float val = input[batch_idx*H + i];
        max_val = fmaxf(max_val, val);
    }
    max_val = warp_reduce_max(max_val);
    if(tid == 0) shared[0] = max_val;
    __syncthreads();
    max_val = shared[0];

    // Compute logsumexp
    float exp_sum = 0.0f;
    for(int i=tid; i<H; i+=blockDim.x) {
        float val = input[batch_idx*H + i];
        exp_sum += expf(val - max_val);
    }
    exp_sum = warp_reduce_sum(exp_sum);

    if(tid == 0) {
        float lse = logf(exp_sum) + max_val;
        // Mish activation
        float sp = log1pf(expf(lse));
        float mish = lse * tanhf(sp);
        output[batch_idx] = mish;
    }
}

torch::Tensor logsumexp_mish_cuda(torch::Tensor input) {
    int B = input.size(0);
    int H = input.size(1);
    auto output = torch::empty(B, input.options());

    dim3 blocks(B);
    dim3 threads(32);
    logsumexp_mish_kernel<<<blocks, threads, sizeof(float)>>>(
        input.data_ptr<float>(), output.data_ptr<float>(), B, H
    );
    return output.unsqueeze(1);
}
"""

# Load CUDA kernels
scale_clamp = load_inline(
    name='scale_clamp',
    cpp_sources="torch::Tensor scale_clamp_cuda(torch::Tensor input, float scale, float clamp_min, float clamp_max);",
    cuda_sources=scale_clamp_source,
    functions=['scale_clamp_cuda'],
    verbose=False
)

logsumexp_mish = load_inline(
    name='logsumexp_mish',
    cpp_sources="torch::Tensor logsumexp_mish_cuda(torch::Tensor input);",
    cuda_sources=logsumexp_mish_source,
    functions=['logsumexp_mish_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, scale_factor, clamp_min, clamp_max):
        super().__init__()
        self.matmul = nn.Linear(input_size, hidden_size)
        self.fused_scale = scale_factor * 2  # Fuse *2 and +x steps
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max

    def forward(self, x):
        x = self.matmul(x)
        x = scale_clamp.scale_clamp_cuda(x, self.fused_scale, self.clamp_min, self.clamp_max)
        x = logsumexp_mish.logsumexp_mish_cuda(x)
        return x
